  configuration = CssDocConfigFile.loadForFolder(repoRoot).toConfiguration();
  tmp = mkdtempSync(join(tmpdir(), "pantoken-cssapi-"));
});
afterAll(() => {
  rmSync(tmp, { recursive: true, force: true });
});

